package com.stylemind.commerce.entity;
import jakarta.persistence.Column; import jakarta.persistence.Entity; import jakarta.persistence.Id; import jakarta.persistence.Table; import java.util.UUID; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter;
@Entity @Table(name="order_item",schema="public") @Getter @Setter @NoArgsConstructor
public class OrderItem { @Id @Column(name="order_item_id") private UUID orderItemId; @Column(name="order_id",nullable=false) private UUID orderId; @Column(name="variant_id",nullable=false) private UUID variantId; @Column(name="sku_snapshot",nullable=false) private String skuSnapshot; @Column(name="product_name_snapshot",nullable=false) private String productNameSnapshot; @Column(name="brand_name_snapshot",nullable=false) private String brandNameSnapshot; @Column(name="color_snapshot") private String colorSnapshot; @Column(name="size_snapshot") private String sizeSnapshot; @Column(name="material_snapshot") private String materialSnapshot; @Column(name="image_url_snapshot") private String imageUrlSnapshot; @Column(nullable=false) private int quantity; @Column(name="unit_price_vnd",nullable=false) private long unitPriceVnd; }
